#!/usr/bin/env bash
# Build a CRYENGINE source tree (the solution generated by CMake in <engine>/win64).
# Adapted from XTFrame-CRYENGINE/tools/build_engine.sh.
#
#   tools/build_engine.sh <engine-root> [Profile|Debug|Release] [msbuild target ...]
#   CRYENGINE_SOURCE=<engine-root> tools/build_engine.sh [Profile|Debug|Release] [msbuild target ...]
#
# Without targets the whole solution is built (ALL_BUILD). Targets are MSBuild solution targets, i.e.
# the CMake target name prefixed with its solution folder path using backslashes (quote them), e.g.
#   'CRYENGINE\CryPlugins\CEVPlayer'   'CRYENGINE\Launcher\WindowsLauncher'   'CRYENGINE\Sandbox\Sandbox'
# Requires <engine>/win64/CRYENGINE_Win64.sln (configure first with the engine-shipped CMake, VS 2022 x64).
# MSBuild is found through vswhere. tools/msbuild/toolset_compat.props is injected for VS 2022 17.8+
# (Qt 5.12 qlist.h vs. the STL4043 deprecation under /WX), so no engine file is edited.
# The log goes to <repo>/build/<engine dir name>-<config>.log.
set -euo pipefail

usage() {
  echo "usage: build_engine.sh [<engine-root>] [Profile|Debug|Release] [msbuild target ...]" >&2
  echo "       (<engine-root> may also come from \$CRYENGINE_SOURCE)" >&2
  exit 2
}

here="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
case "${1:-}" in -h|--help) usage ;; esac

engine="${CRYENGINE_SOURCE:-}"
if [ "$#" -gt 0 ] && [ -d "$1" ]; then engine="$1"; shift; fi
[ -n "$engine" ] || usage
config="Profile"
case "${1:-}" in Profile|Debug|Release) config="$1"; shift ;; esac

engine="$(cd "$engine" && pwd)"
sln="$engine/win64/CRYENGINE_Win64.sln"
[ -f "$sln" ] || { echo "build_engine: $sln not found (configure the engine with CMake first)" >&2; exit 1; }
vswhere="/c/Program Files (x86)/Microsoft Visual Studio/Installer/vswhere.exe"
[ -x "$vswhere" ] || { echo "build_engine: vswhere not found at $vswhere" >&2; exit 1; }
msbuild="$("$vswhere" -latest -requires Microsoft.Component.MSBuild -find 'MSBuild/**/Bin/MSBuild.exe' | head -n1 | tr -d '\r')"
[ -n "$msbuild" ] || { echo "build_engine: MSBuild not found via vswhere" >&2; exit 1; }
props="$(cygpath -w "$here/tools/msbuild/toolset_compat.props")"
mkdir -p "$here/build"
log="$here/build/$(basename "$engine")-$config.log"

targets=()
if [ "$#" -gt 0 ]; then
  joined="$(IFS=';'; echo "$*")"
  targets=("-t:$joined")
fi

echo "build_engine: $config ${*:-(whole solution)} -> $log"
start=$(date +%s)
"$msbuild" "$(cygpath -w "$sln")" "${targets[@]}" \
  -p:Configuration="$config" -p:Platform=x64 -m -nologo -v:m \
  -p:ForceImportBeforeCppTargets="$props" \
  "-clp:Summary;ErrorsOnly" "-flp:LogFile=$(cygpath -w "$log");Verbosity=minimal" \
  || { echo "build_engine: FAILED after $(( $(date +%s) - start )) s, see $log" >&2; exit 1; }
echo "build_engine: done in $(( $(date +%s) - start )) s -> $engine/bin/win_x64"
